/*
* This script compiles modules for evaluating polynomial functions. If any polynomial coefficients change, this script should be rerun to update the compiled files.
*/

'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var readFileSync = require( '@stdlib/fs/read-file' ).sync;
var writeFileSync = require( '@stdlib/fs/write-file' ).sync;
var currentYear = require( '@stdlib/time/current-year' );
var licenseHeader = require( '@stdlib/_tools/licenses/header' );
var compile = require( '@stdlib/math/base/tools/evalpoly-compile' );
var compileC = require( '@stdlib/math/base/tools/evalpoly-compile-c' );
var substringBefore = require( '@stdlib/string/substring-before' );
var substringAfter = require( '@stdlib/string/substring-after' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

// Polynomial coefficients ordered in ascending degree...

// S(x) for small x:
var SN = [
	5.235987735681432e-1,
	-9.228055941124598e-2,
	7.244727626597022e-3,
	-3.120693124703272e-4,
	8.424748808502400e-6,
	-1.522754752581096e-7,
	1.647629463788700e-9
];

// C(x) for small x:
var CN = [
	9.999999760004487e-1,
	-2.467398198317899e-1,
	2.818489036795073e-2,
	-1.604381798862293e-3,
	5.387223446683264e-5,
	-1.157231412229871e-6,
	1.416802502367354e-8
];

// Auxiliary function f(x):
var FN = [
	2.999401847870011e0,
	-1.032877601091159e2,
	8.560515466275470e3,
	-8.732356681548485e5,
	7.343848463587323e7,
	-4.158143148511033e9,
	1.355942388050252e11,
	-1.903009855649792e12
];

// Auxiliary function g(x):
var GN = [
	9.999841934744914e-1,
	-1.493439396592284e1,
	8.602931494734327e2,
	-7.787789623358162e4,
	6.492611570598858e6,
	-3.779387713202229e8,
	1.278350673393208e10,
	-1.860843997624650e11
];

// Header to add to output files:
var header = licenseHeader('Apache-2.0', 'js', {
	'year': currentYear(),
	'copyright': 'The Stdlib Authors'
});
header += '\n/* This is a generated file. Do not edit directly. */\n';


// FUNCTIONS //

/**
* Inserts a compiled function into file content.
*
* @private
* @param {string} text - source content
* @param {string} id - function identifier
* @param {string} str - function string
* @returns {string} updated content
*/
function insert( text, id, str ) {
	var before;
	var after;
	var begin;
	var end;

	begin = '// BEGIN: '+id;
	end = '// END: '+id;

	before = substringBefore( text, begin );
	after = substringAfter( text, end );

	return format( '%s// BEGIN: %s\n\n%s\n%s%s', before, id, str, end, after );
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var fpath;
	var copts;
	var opts;
	var file;
	var str;

	opts = {
		'encoding': 'utf8'
	};

	fpath = resolve( __dirname, '..', 'lib', 'polyval_sn.js' );
	str = header + compile( SN, {
		'dtype': 'float32'
	});
	writeFileSync( fpath, str, opts );

	fpath = resolve( __dirname, '..', 'lib', 'polyval_cn.js' );
	str = header + compile( CN, {
		'dtype': 'float32'
	});
	writeFileSync( fpath, str, opts );

	fpath = resolve( __dirname, '..', 'lib', 'polyval_fn.js' );
	str = header + compile( FN, {
		'dtype': 'float32'
	});
	writeFileSync( fpath, str, opts );

	fpath = resolve( __dirname, '..', 'lib', 'polyval_gn.js' );
	str = header + compile( GN, {
		'dtype': 'float32'
	});
	writeFileSync( fpath, str, opts );

	copts = {
		'dtype': 'float',
		'name': ''
	};

	fpath = resolve( __dirname, '..', 'src', 'main.c' );
	file = readFileSync( fpath, opts );

	copts.name = 'polyval_sn';
	str = compileC( SN, copts );
	file = insert( file, copts.name, str );

	copts.name = 'polyval_cn';
	str = compileC( CN, copts );
	file = insert( file, copts.name, str );

	copts.name = 'polyval_fn';
	str = compileC( FN, copts );
	file = insert( file, copts.name, str );

	copts.name = 'polyval_gn';
	str = compileC( GN, copts );
	file = insert( file, copts.name, str );

	writeFileSync( fpath, file, opts );
}

main();
